            print(f"Error: {e}")

    elif args.compare:
        reports = manager.compare_reports(args.compare)
        if reports:
            print(f"Comparison reports for {args.compare}:")
            for report in reports:
                print(f"  {report}")
        else:
            print(f"No reports found for type: {args.compare}")

