def monitor_system():
    try:
        # Monitor system logs for AutoBot-related entries
        proc = subprocess.Popen(
            [
                "journalctl",
                "-f",
                "--no-pager",
                "--grep=autobot|AutoBot|python|docker",
            ],
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
        )

        for line in iter(proc.stdout.readline, ""):
            if not self.running:
                proc.terminate()
                break

            if line.strip() and (
