        elif stats["success_rate"] >= 70:
            print("   🟠 FAIR - System is functional but needs attention")
        else:
            print("   🔴 POOR - System has significant issues requiring immediate attention")

        # Recommendations
        print(f"\n💡 Key Recommendations:")
        if severity["critical"] > 0:
