                name="Knowledge Base Search",
                success=False,
                message=f"Search request failed: {str(e)}"
            ))

        return results

    async def test_chat_functionality(self) -> List[TestResult]:
        """Test chat system functionality"""
        results = []

        # Test chat creation using the correct endpoint
        try:
